namespace RealEstatePro\Subscriptions;defined('ABSPATH')||exit;
final class SubscriptionManager{public function register():void{foreach(['woocommerce_subscription_status_active','woocommerce_subscription_status_cancelled','woocommerce_subscription_status_expired','woocommerce_subscription_status_on-hold'] as $h)add_action($h,[$this,'sync']);}public function sync($s):void{if(!is_object($s)||!method_exists($s,'get_user_id'))return;$uid=(int)$s->get_user_id();$tier='free';if(method_exists($s,'get_status')&&$s->get_status()==='active'){$n=strtolower(implode(' ',array_map(static fn($i)=>$i->get_name(),$s->get_items())));$tier=str_contains($n,'vip')?'vip':(str_contains($n,'pro')?'pro':'free');}update_user_meta($uid,'re_pro_customer_tier',$tier);}}